'use strict';
const $=id=>document.getElementById(id),fmt=n=>n===null?'Unavailable':Number(n).toLocaleString('en-IN'),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fieldMap={name:'event-name',venue:'venue',date:'date',time:'time',attendance:'attendance',carShare:'car-share',occupancy:'occupancy',parking:'parking',window:'window',duration:'duration',shuttles:'shuttles',extraParking:'extra-parking',stagger:'stagger'};
let snapshot,results,current='b',closedRoads=[],step=4,playTimer=null,leaflet,roadLayers,markerLayers,emergencyLayer,alternatives=[];
const metrics=[['Additional car trips','cars',' cars'],['Peak hourly arrivals','peak',' cars/h'],['Average approach travel','travel',' min'],['Busy road segments','affected',''],['Peak parking demand','demand',' spaces'],['Parking shortfall','shortage',' spaces'],['Emergency route time','emergency',' min'],['Unreachable approaches','unreachable',' / 4']];
function readInputs(){const v={closedRoads:[...closedRoads]};Object.entries(fieldMap).forEach(([key,id])=>v[key]=['name','venue','date','time'].includes(key)?$(id).value: +$(id).value);if(window.PlanningUI)Object.assign(v,PlanningUI.read());return UrbanModel.validate(v);}
function fillInputs(v){UrbanModel.validate(v);Object.entries(fieldMap).forEach(([key,id])=>$(id).value=v[key]);closedRoads=[...v.closedRoads];if(window.PlanningUI)PlanningUI.fill(v);$('attendance-value').textContent=fmt(v.attendance);}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function run(event){if(event)event.preventDefault();if(!$('event-form').reportValidity())return false;try{snapshot=readInputs();results={a:UrbanModel.simulate(snapshot,'a'),b:UrbanModel.simulate(snapshot,'b')};step=Math.min(step,results[current].timeline.length-1);render();$('form-note').textContent='Results updated. Saved/exported plans use current inputs.';if(event)notify('Both scenarios updated.');return true;}catch(error){notify(error.message);return false;}}
function palette(print=false){return !print&&document.documentElement.dataset.theme==='dark'?{free:'#38cfdd',busy:'#f6b93b',congested:'#ff687d',emergency:'#b99aff',closed:'#cad5df'}:{free:'#087f8c',busy:'#b77900',congested:'#d13e51',emergency:'#7649d4',closed:'#384253'};}
function color(r,print=false){const p=palette(print);return r.closed?p.closed:r.ratio>=1?p.congested:r.ratio>=.85?p.busy:p.free;}
function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';$('theme-toggle').textContent=dark?'Light theme':'Dark theme';$('theme-toggle').setAttribute('aria-pressed',String(dark));$('theme-toggle').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');}
function timeLabel(t){const [h,m]=snapshot.time.split(':').map(Number);const total=h*60+m+t*60;const day=Math.floor(total/1440);const minute=((total%1440)+1440)%1440;return `${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}${day?` (${day>0?'+':''}${day} day)`:''}`;}
function render(){const r=results[current];document.querySelectorAll('[data-scenario]').forEach(b=>{b.classList.toggle('selected',b.dataset.scenario===current);b.setAttribute('aria-pressed',b.dataset.scenario===current);});$('map-state').textContent=`Scenario ${current.toUpperCase()} · ${r.closed.length} closed segments`;$('report-context').textContent=`${snapshot.name} · ${snapshot.date} at ${snapshot.time} · ${fmt(snapshot.attendance)} attendees · Viewing ${current.toUpperCase()}`;
const cards=[['Additional car trips',r.cars,'cars',`${fmt(r.peak)} cars / peak hour`],['Average approach travel',r.travel,'min',r.unreachable?`${r.unreachable} approach(es) unreachable; average excludes them`:`Across 4 approach routes`],['Peak parking demand',r.demand,'spaces',r.shortage?`${fmt(r.shortage)} spaces over supply`:`${fmt(r.supply-r.demand)} spaces available`],['Emergency route',r.emergency,'min',r.emergency===null?'No route in study area':r.emergency>10?'Above 10-minute demo threshold':'Mapped route found · access unverified']];
$('metrics').innerHTML=cards.map(([label,value,unit,note],i)=>`<article class="metric"><div class="metric-label">${label}<span>0${i+1}</span></div><div class="metric-value">${fmt(value)} <small>${value===null?'':unit}</small></div><div class="metric-note">${note}</div></article>`).join('');
$('comparison-body').innerHTML=metrics.map(([label,k,unit])=>{const a=results.a[k],b=results.b[k],d=a===null||b===null?null:+(b-a).toFixed(1);return `<tr><td>${label}</td><td>${fmt(a)}${a===null?'':unit}</td><td>${fmt(b)}${b===null?'':unit}</td><td><span class="delta ${d!==null&&d<=0?'neutral':''}">${d===null?'Route unavailable':d===0?'No change':`${d>0?'+':''}${fmt(d)}${unit}`}</span></td></tr>`;}).join('');
$('map-insight').textContent=r.unreachable?`${r.unreachable} of 4 approaches cannot reach the venue within this road snapshot. Reopen connecting segments before interpreting average travel time.`:`${r.affected} road segments exceed 85% of assumed capacity at peak. Select a segment to inspect it or toggle its closure in B.`;
$('closed-list').textContent=closedRoads.length?`Closed in B: ${closedRoads.map(id=>UrbanModel.roads.find(x=>x.id===id)?.name+' #'+id).join(', ')}`:'All mapped roads are open in B.';
updateRoadButton();renderMap(r);renderTimeline();renderParking(r);renderSuggestions();renderFindings(r);if(window.PlanningUI)PlanningUI.render();}
function renderFindings(r){const b=results.b,a=results.a;const better=b.shortage<a.shortage?`The proposed plan reduces the parking shortfall by ${fmt(a.shortage-b.shortage)} spaces. `:'';$('recommendation').textContent=better+(b.unreachable?'The proposed closures disconnect an approach in the bounded network. Review connectivity before comparing travel times.':'Compare route delays and parking demand together. More parking addresses space shortages; shuttles and staggered arrivals address traffic pressure.');const issues=[['P',r.shortage?'Find overflow parking':'Parking fits modeled demand',r.shortage?`${fmt(r.shortage)} cars exceed total supply. Use the additional-parking suggestion or reduce car arrivals.`:`${fmt(r.supply-r.demand)} spaces remain at peak. Confirm usable spaces locally.`],['↗',r.emergency===null?'Emergency route is disconnected':'Protect the emergency route',r.emergency===null?'No mapped route was found. Reopen roads or expand the study area; this is not proof that no real-world route exists.':`${r.emergency} minutes from ${UrbanModel.hospital.name} to the modeled access node. The hospital access node is ${Math.round(r.accessOffsetKm*1000)} m from its mapped center; final access and clearance are unverified.`],['◷','Manage the peak',`${fmt(r.peak)} cars/hour arrive at peak. Use the timeline to compare arrivals with departures; extend arrivals or add shuttles to reduce pressure.`]];$('findings').innerHTML=issues.map(([i,t,b])=>`<article class="finding"><span class="finding-icon">${i}</span><div><h3>${t}</h3><p>${escapeHTML(b)}</p></div></article>`).join('');}
function initMap(){if(!window.L){$('geo-map').textContent='Map library unavailable. Choose Traffic animation to use the packaged road geometry.';return;}leaflet=L.map('geo-map',{preferCanvas:true}).setView([30.740,76.780],15);leaflet.attributionControl.addAttribution('&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors');L.control.scale({imperial:false}).addTo(leaflet);roadLayers=L.layerGroup().addTo(leaflet);markerLayers=L.layerGroup().addTo(leaflet);emergencyLayer=L.layerGroup().addTo(leaflet);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'origin',updateWhenIdle:true,keepBuffer:1});let timer;const offline=()=>{clearTimeout(timer);if(leaflet.hasLayer(tiles))leaflet.removeLayer(tiles);$('map-background').value='packaged';};tiles.on('tileerror',()=>{offline();$('tile-status').textContent='Online background unavailable. Showing packaged OpenStreetMap roads and place markers; no background tiles are needed.';});tiles.on('load',()=>{clearTimeout(timer);if(leaflet.hasLayer(tiles))$('tile-status').textContent='Online OpenStreetMap background. Traffic and parking capacities are demo estimates.';});$('map-background').onchange=event=>{const online=event.target.value==='online';offline();if(online){$('map-background').value='online';$('tile-status').textContent='Loading online street background…';timer=setTimeout(()=>{offline();$('tile-status').textContent='Street background did not load. Showing packaged roads and place markers.';},10000);tiles.addTo(leaflet);}else $('tile-status').textContent='Packaged OpenStreetMap road snapshot · works without online tiles. Traffic and capacities are demo estimates.';};$('tile-status').textContent='Packaged OpenStreetMap road snapshot · works without online tiles. Traffic and capacities are demo estimates.';}
function renderMap(r){if(leaflet){roadLayers.clearLayers();markerLayers.clearLayers();emergencyLayer.clearLayers();r.network.forEach(road=>{const line=L.polyline(road.points,{color:color(road),weight:road.kind==='secondary'?5:3,opacity:road.closed?1:.72,dashArray:road.closed?'6 7':null}).addTo(roadLayers);const wrap=document.createElement('div'),title=document.createElement('strong'),p=document.createElement('p'),button=document.createElement('button');title.textContent=`${road.name} · ${road.id}`;p.textContent=road.closed?'Closed in proposed plan':`${fmt(road.volume)} modeled vehicles/hour · ${Math.round(road.ratio*100)}% assumed capacity`;button.textContent=closedRoads.includes(road.id)?'Reopen in B':'Close in B';button.className='button light';button.onclick=()=>toggleRoad(road.id);wrap.append(title,p,button);line.bindPopup(wrap);line.on('click',()=>{$('road-select').value=road.id;updateRoadButton();});});
const point=(p,label,background)=>L.marker(p,{icon:L.divIcon({className:'place-marker',html:`<span style="background:${background}">${label}</span>`,iconSize:[28,28]})}).addTo(markerLayers);
point(r.venue.point,'E','#274e3c').bindTooltip(r.venue.name,{permanent:true,direction:'top'});point(UrbanModel.hospital.point,'H','#477f9d').bindTooltip(UrbanModel.hospital.name);
r.parking.forEach((p,i)=>point(p.point,`P${i+1}`,p.free?'#66824b':'#bb7b42').bindTooltip(`${p.name}: ${p.occupied}/${p.capacity} spaces (assumed)`));
if(r.emergencyRoute)L.polyline(r.emergencyRoute.points,{color:palette().emergency,weight:4,dashArray:'8 6'}).addTo(emergencyLayer).bindTooltip('Modeled emergency route to nearest venue access node');}
renderAnimation();}
const bounds={south:30.730,north:30.753,west:76.767,east:76.797};
function project(p){return [35+(p[1]-bounds.west)/(bounds.east-bounds.west)*780,465-(p[0]-bounds.south)/(bounds.north-bounds.south)*440];}
function pathFor(points){return points.map((p,i)=>{const [x,y]=project(p);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;}).join(' ');}
function renderAnimation(){const r=results[current],slot=r.timeline[step],factor=r.peak?((slot.arrival+slot.departure)*2/r.peak):0;const visible=r.network.filter(x=>x.kind!=='service');$('animation-map').innerHTML=`<rect width="850" height="490" fill="#edf1e9"/><text x="25" y="25" fill="#4d6954" font-size="14">${escapeHTML(r.venue.name)} · ${timeLabel(slot.t)} · illustrative flow</text><g>${visible.map(road=>`<path data-road-id="${road.id}" d="${pathFor(road.points)}" stroke="${color(road)}" stroke-width="${road.closed?3:1.5}" opacity=".6" fill="none" ${road.closed?'stroke-dasharray="4 4"':''}/>`).join('')}</g>${r.emergencyRoute?`<path d="${pathFor(r.emergencyRoute.points)}" fill="none" stroke="${palette().emergency}" stroke-width="3" stroke-dasharray="7 5"/>`:''}${visible.filter(x=>!x.closed&&x.ratio>x.baseline+.01).map(road=>{const n=window.matchMedia("(prefers-reduced-motion: reduce)").matches?0:Math.min(7,Math.ceil(factor*road.ratio*3));const seconds=Math.max(2,Math.min(12,4*road.ratio));return Array.from({length:n},(_,i)=>`<circle r="2.7" fill="${color(road)}"><animateMotion dur="${seconds}s" begin="-${i*seconds/Math.max(n,1)}s" repeatCount="indefinite" path="${pathFor(road.oneway===-1?[...road.points].reverse():road.points)}"/></circle>${road.ratio*factor>1?`<circle cx="${project(road.points[0])[0]+i*4}" cy="${project(road.points[0])[1]}" r="2" fill="#bd624e"/>`:''}`).join('');}).join('')}${r.parking.map((p,i)=>{const [x,y]=project(p.point);return `<circle cx="${x}" cy="${y}" r="10" fill="#75915d"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-size="10">P${i+1}</text>`;}).join('')}<circle cx="${project(r.venue.point)[0]}" cy="${project(r.venue.point)[1]}" r="10" fill="#244e3e"/><text x="25" y="480" fill="#6d8068" font-size="11">Road geometry © OpenStreetMap contributors · synthetic traffic · purple dashed line: emergency route</text>`;}
function renderTimeline(){const r=results[current],slots=r.timeline,max=Math.max(1,...slots.map(s=>Math.max(s.arrival,s.departure))),w=920/slots.length;step=Math.min(step,slots.length-1);$('time-step').max=slots.length-1;$('time-step').value=step;$('time-label').textContent=timeLabel(slots[step].t);$('timeline-chart').innerHTML=`<line x1="40" y1="135" x2="970" y2="135" stroke="#ccd7c5"/>${slots.map((s,i)=>{const h=Math.max(s.arrival,s.departure)/max*90;return `<rect x="${40+i*w}" y="${135-h}" width="${w-4}" height="${Math.max(h,2)}" rx="3" fill="${s.departure?'#d59b60':'#729762'}" opacity="${i===step?1:.6}"/><text x="${40+i*w}" y="${i%2?164:151}" font-size="10" fill="#708267">${timeLabel(s.t).split(' ')[0]}</text>${i===step?`<line x1="${40+i*w+w/2}" x2="${40+i*w+w/2}" y1="15" y2="135" stroke="#2f5240" stroke-dasharray="4 4"/>`:''}`;}).join('')}<text x="40" y="13" font-size="11" fill="#6e8068">Maximum ${fmt(max)} cars / half hour · ${snapshot.date}</text>`;$('time-summary').textContent=`${timeLabel(slots[step].t)}–${timeLabel(slots[step].t+.5)}: ${fmt(slots[step].arrival)} arriving · ${fmt(slots[step].departure)} departing · ${fmt(slots[step].parked)} parked (estimated)`;renderAnimation();syncMapTime();}
function renderParking(r){$('parking-summary').textContent=`${fmt(r.demand)} needed / ${fmt(r.supply)} supplied`;$('parking-cards').innerHTML=r.parking.map((p,i)=>`<article class="parking-card"><span class="parking-icon">P${i+1}</span><h3>${escapeHTML(p.name)}</h3><p>${fmt(p.occupied)} / ${fmt(p.capacity)} spaces</p><progress value="${p.occupied}" max="${p.capacity||1}" aria-label="${escapeHTML(p.name)} occupancy"></progress><p>${p.free?`${fmt(p.free)} spaces free · alternative for overflow`:'Full at modeled peak'}${p.proposed?' · proposed site':''}</p><button class="button light" data-parking="${i}">Show on map</button></article>`).join('');document.querySelectorAll('[data-parking]').forEach(b=>b.onclick=()=>{$('view').value='geo';setView();leaflet?.setView(r.parking[+b.dataset.parking].point,17);window.AppPages?.reveal($('geo-map'));$('geo-map').scrollIntoView({behavior:'smooth',block:'center'});});}
function renderSuggestions(){const base=results.b;alternatives=[{name:'Add 5 shuttle buses',description:'Up to 400 car passengers switch to shared transport.',change:{shuttles:Math.min(100,snapshot.shuttles+5)}},{name:'Cover the parking shortfall',description:'Add remote spaces without changing road demand.',change:{extraParking:Math.min(5000,snapshot.extraParking+Math.max(100,base.shortage))}},{name:'Spread arrivals over 3 hours',description:'Extend arrival times to soften the peak.',change:{stagger:3-snapshot.window}}];$('improvement-options').innerHTML=alternatives.map((v,i)=>{const next=UrbanModel.simulate({...snapshot,...v.change},'b');return `<article><h3>${v.name}</h3><p>${v.description}</p><strong>${fmt(next.peak)} cars/h · ${fmt(next.shortage)} spaces short</strong><p>Current B: ${fmt(base.peak)} cars/h · ${fmt(base.shortage)} short</p><button class="button lime" data-improvement="${i}" ${Object.entries(v.change).every(([k,val])=>snapshot[k]===val)?'disabled':''}>Apply to B</button></article>`;}).join('');document.querySelectorAll('[data-improvement]').forEach(b=>b.onclick=()=>{if(!run())return;fillInputs({...snapshot,...alternatives[+b.dataset.improvement].change});current='b';run();notify('Improvement applied to Scenario B.');});}
function updateRoadButton(){$('toggle-road').textContent=closedRoads.includes($('road-select').value)?'Reopen in B':'Close in B';}
function toggleRoad(id){if(!$('event-form').reportValidity())return;closedRoads=closedRoads.includes(id)?closedRoads.filter(v=>v!==id):[...closedRoads,id];current='b';run();notify('Road restriction updated in B.');}
function setView(){const animation=$('view').value==='animation';$('geo-map').hidden=animation;$('animation-view').hidden=!animation;$('map-time-controls').hidden=!animation;if(!animation)requestAnimationFrame(()=>leaflet?.invalidateSize());}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const storageKey='urbanpulse-scenarios-v2';
function savedPlans(){try{return JSON.parse(localStorage.getItem(storageKey)||'[]').filter(v=>v&&v.plan&&v.id);}catch{return [];}}
function refreshLibrary(){const items=savedPlans();$('saved').replaceChildren(new Option('Choose saved scenario',''),...items.map(v=>new Option(v.plan.name+' · '+new Date(v.savedAt).toLocaleString(),v.id)));}
function savePlan(){try{const plan=readInputs(),items=savedPlans();const id=String(Date.now());items.push({id,savedAt:new Date().toISOString(),plan});localStorage.setItem(storageKey,JSON.stringify(items.slice(-30)));refreshLibrary();$('saved').value=id;notify('Saved in this browser. Export a file for another device.');}catch(e){notify('Could not save: '+e.message);}}
function reportText(){return `URBANPULSE EVENT IMPACT REPORT\n${snapshot.name}\n${snapshot.date} ${snapshot.time}\nREAL MAP — SYNTHETIC ESTIMATES\n\nINPUTS\n${JSON.stringify(snapshot,null,2)}\n\nCOMPARISON\n${metrics.map(([label,k,u])=>`${label}: A ${fmt(results.a[k])}${u}; B ${fmt(results.b[k])}${u}`).join('\n')}\n\nPLANNING BRIEF\n${$('recommendation').textContent}\n\n${document.querySelector('.assumptions').textContent}\n\nSource: https://www.openstreetmap.org/copyright\nMap snapshot: ${CityData.downloaded}\nGenerated: ${new Date().toISOString()}`;}
function reportMap(r){return `<svg viewBox="0 0 850 490" xmlns="http://www.w3.org/2000/svg"><rect width="850" height="490" fill="#f1f4ec"/>${r.network.map(road=>`<path d="${pathFor(road.points)}" fill="none" stroke="${color(road,true)}" stroke-width="${road.closed?4:1.3}" ${road.closed?'stroke-dasharray="5 4"':''}/>`).join('')}${r.emergencyRoute?`<path d="${pathFor(r.emergencyRoute.points)}" fill="none" stroke="#7649d4" stroke-width="4" stroke-dasharray="7 5"/>`:''}${r.parking.map((p,i)=>{const [x,y]=project(p.point);return `<circle cx="${x}" cy="${y}" r="10" fill="#46673b"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-size="11">P${i+1}</text>`;}).join('')}<circle cx="${project(r.venue.point)[0]}" cy="${project(r.venue.point)[1]}" r="11" fill="#152e24"/><text x="20" y="28" fill="#344e39" font-size="15">${escapeHTML(r.venue.name)} · Scenario ${r===results.a?'A':'B'}</text><text x="20" y="478" font-size="11">© OpenStreetMap contributors · red: congestion · gray dashed: closure · purple dashed: emergency route</text></svg>`;}
function printReport(){if(!run())return;const dialog=document.getElementById("report-dialog");dialog.showModal();const report=document.getElementById("report-frame").contentWindow;report.document.open();const rows=metrics.map(([label,k,u])=>`<tr><td>${label}</td><td>${fmt(results.a[k])}${results.a[k]===null?'':u}</td><td>${fmt(results.b[k])}${results.b[k]===null?'':u}</td></tr>`).join('');report.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>UrbanPulse — ${escapeHTML(snapshot.name)}</title><style>body{font:14px/1.6 Arial,sans-serif;color:#203a30;max-width:1000px;margin:32px auto;padding:0 20px}h1{line-height:1.2}h2{font-size:19px;margin-top:28px}small{color:#69786c}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:9px;border-bottom:1px solid #dce5d9}svg{width:100%;max-height:400px}section{break-inside:avoid}.maps{display:grid;grid-template-columns:1fr 1fr}button{padding:12px 20px;background:#244636;color:white;border:0;cursor:pointer}@media print{button,.print-help{display:none}body{margin:0;font-size:11px}h1{font-size:25px}.maps svg{max-height:250px}a{color:inherit} @page{size:A4;margin:14mm}} </style></head><body><button onclick="window.print()">Print / Save as PDF</button><p class="print-help">In the print dialog, choose “Save as PDF” to create a shareable file. Maps are embedded and work offline.</p><small>URBANPULSE · IMPACT REPORT · DEMONSTRATION ESTIMATES</small><h1>${escapeHTML(snapshot.name)}</h1><p>${escapeHTML(results.a.venue.name)} · ${snapshot.date} at ${snapshot.time} · ${snapshot.duration} hours</p><section><h2>Event and planning inputs</h2><p>${fmt(snapshot.attendance)} attendees · ${snapshot.carShare}% car share · ${snapshot.occupancy} people/car · ${snapshot.parking} base parking spaces · ${snapshot.window}-hour arrivals.</p><p>B: ${snapshot.shuttles} shuttle buses (40 seats, 2 trips), ${snapshot.extraParking} extra spaces, ${results.b.window}-hour arrivals; ${snapshot.closedRoads.length} road segments closed.</p><p>Closed segments: ${escapeHTML(snapshot.closedRoads.map(id=>UrbanModel.roads.find(r=>r.id===id).name+' #'+id).join(', ')||'None')}.</p></section><section><h2>Scenario comparison</h2><table><tr><th>Measure</th><th>A · Original</th><th>B · Proposed</th></tr>${rows}</table><p>Unreachable routes are excluded from the average; no route means no connection found within this snapshot.</p></section><section><h2>Mapped roads and emergency routes</h2><div class="maps">${reportMap(results.a)}${reportMap(results.b)}</div></section><section><h2>Parking plan · B</h2><table><tr><th>Site</th><th>Assumed capacity</th><th>Peak occupancy</th></tr>${results.b.parking.map((p,i)=>`<tr><td>P${i+1} · ${escapeHTML(p.name)}</td><td>${p.capacity}</td><td>${p.occupied}</td></tr>`).join('')}</table></section><section><h2>Arrival and departure timeline · B</h2><table><tr><th>Half-hour interval starts</th><th>Arrivals</th><th>Departures</th><th>Parked</th></tr>${results.b.timeline.map(s=>`<tr><td>${timeLabel(s.t)}</td><td>${s.arrival}</td><td>${s.departure}</td><td>${s.parked}</td></tr>`).join('')}</table></section><h2>Planning brief</h2><p>${escapeHTML($('recommendation').textContent)}</p><h2>Assumptions and limitations</h2>${Array.from(document.querySelectorAll('.assumptions p')).map(p=>`<p>${escapeHTML(p.textContent)}</p>`).join('')}<p>Source: <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors, ODbL</a> · Snapshot ${CityData.downloaded} · Generated ${new Date().toISOString()}</p></body></html>`);if(window.PlanningUI)report.document.write(PlanningUI.report());report.document.close();}
$('event-form').addEventListener('submit',run);$('event-form').addEventListener('input',()=>{$('attendance-value').textContent=fmt($('attendance').value);$('form-note').textContent='Inputs changed. Run simulation to update results.';});
document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{current=b.dataset.scenario;render();});
$('road-select').replaceChildren(...UrbanModel.roads.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(r=>new Option(`${r.name} · #${r.id}`,r.id)));$('road-select').onchange=updateRoadButton;$('toggle-road').onclick=()=>toggleRoad($('road-select').value);$('clear-roads').onclick=()=>{closedRoads=[];run();};$('view').onchange=setView;$('fit-map').onclick=()=>leaflet?.setView([30.740,76.780],15);
function syncMapTime(){const r=results[current];$('map-time-step').max=r.timeline.length-1;$('map-time-step').value=step;$('map-time-label').textContent=timeLabel(r.timeline[step].t);$('map-time-summary').textContent=$('time-summary').textContent;$('map-time-back').disabled=step===0;$('map-time-forward').disabled=step===r.timeline.length-1;$('map-time-play').textContent=playTimer?'Pause':'Play';$('map-time-play').setAttribute('aria-pressed',String(!!playTimer));}
function stopTimeline(){clearInterval(playTimer);playTimer=null;$('play').textContent='Play timeline';$('play').setAttribute('aria-pressed','false');syncMapTime();}
function playTimeline(){if(playTimer){stopTimeline();return;}$('view').value='animation';setView();$('play').textContent='Pause timeline';$('play').setAttribute('aria-pressed','true');playTimer=setInterval(()=>{if(step>=results[current].timeline.length-1){stopTimeline();return;}step++;renderTimeline();},+$('map-time-speed').value);syncMapTime();}
function seekTimeline(value){stopTimeline();step=Math.max(0,Math.min(results[current].timeline.length-1,value));renderTimeline();}
$('time-step').oninput=()=>seekTimeline(+$('time-step').value);$('map-time-step').oninput=()=>seekTimeline(+$('map-time-step').value);$('map-time-back').onclick=()=>seekTimeline(step-1);$('map-time-forward').onclick=()=>seekTimeline(step+1);$('play').onclick=playTimeline;$('map-time-play').onclick=()=>{if(!playTimer&&step>=results[current].timeline.length-1)step=0;playTimeline();};$('map-time-speed').onchange=()=>{if(playTimer){stopTimeline();playTimeline();}};
$('save').onclick=savePlan;$('load').onclick=()=>{try{const saved=savedPlans().find(p=>p.id===$('saved').value);if(!saved)return notify('Choose a saved scenario first.');fillInputs(saved.plan);run();notify('Saved scenario loaded.');}catch(e){notify(e.message);}};
$('export-plan').onclick=()=>{try{download('urbanpulse-scenario.json',JSON.stringify({version:3,plan:readInputs()},null,2),'application/json');notify('Scenario exported for another device.');}catch(e){notify(e.message);}};$('import-plan').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];try{if(!file)return;if(file.size>200000)throw Error('Scenario file is too large.');const data=JSON.parse(await file.text());if(![2,3].includes(data.version))throw Error('Unsupported scenario version.');fillInputs(data.plan);run();notify('Scenario imported. Save it to keep it in this browser.');}catch(error){notify('Import failed: '+error.message);}finally{e.target.value='';}};
$('download-report').onclick=printReport;$('print-report').onclick=printReport;$('text-report').onclick=()=>{if(run())download('urbanpulse-impact-report.txt',reportText(),'text/plain;charset=utf-8');};
$('close-report').onclick=()=>$('report-dialog').close();
$('download-html').onclick=()=>download('urbanpulse-report.html','<!doctype html>'+ $('report-frame').contentDocument.documentElement.outerHTML,'text/html;charset=utf-8');
$('theme-toggle').onclick=()=>{const mode=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=mode;try{localStorage.setItem('urbanpulse-theme',mode);}catch{}updateThemeButton();render();};
updateThemeButton();initMap();refreshLibrary();run();






$('animation-map').addEventListener('click',event=>{const path=event.target.closest('[data-road-id]');if(!path)return;$('road-select').value=path.dataset.roadId;updateRoadButton();const road=results[current].network.find(r=>r.id===path.dataset.roadId);if(road)notify(road.name+' selected. Use Close in B / Reopen in B below the animation.');});
